#' Data Preparation (Age Groups & Raking)
#'
#' 
#' @param data the data as a data frame
#' @param age a continuous variable (such as age) to split into discrete norm
#'   groups
#' @param nGroups .
#' @param equidistant .
#' @param stratVars stratification variables for computing raking weights
#' @param margins target population proportions per stratification variable
#'   and level
#' @param standardized .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$groupTab} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$groupPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$marginsTab} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$weightSummaryTab} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$saveGroups} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$saveWeights} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$groupTab$asDF}
#'
#' \code{as.data.frame(results$groupTab)}
#'
#' @export
preparation <- function(
    data,
    age = NULL,
    nGroups = 0,
    equidistant = FALSE,
    stratVars = NULL,
    margins = "",
    standardized = TRUE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("preparation requires jmvcore to be installed (restart may be required)")

    if ( ! missing(age)) age <- jmvcore::resolveQuo(jmvcore::enquo(age))
    if ( ! missing(stratVars)) stratVars <- jmvcore::resolveQuo(jmvcore::enquo(stratVars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(age), age, NULL),
            `if`( ! missing(stratVars), stratVars, NULL))


    options <- preparationOptions$new(
        age = age,
        nGroups = nGroups,
        equidistant = equidistant,
        stratVars = stratVars,
        margins = margins,
        standardized = standardized)

    analysis <- preparationClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

